<section class="card"><div class="section-heading"><div><h2>Pedidos de compra</h2><p>Marque como comprado apenas após receber os equipamentos. Essa ação adiciona a quantidade ao estoque.</p></div><a class="button" href="fazerpedidos.php">＋ Novo pedido</a></div><div class="table-wrap"><table><thead><tr><th>EPI</th><th>Quantidade</th><th>Data</th><th>Observação</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($purchases as $p): ?><tr><td><small>#<?= (int)$p['id_pedido'] ?></small><strong><?= e($p['nome_epi']) ?></strong></td><td><?= (int)$p['quantidade'] ?></td><td><?= e(dateBr($p['data_pedido'])) ?></td><td class="long-text"><?= e($p['observacao']?:'—') ?></td><td><?= badge($p['status_pedido']) ?></td><td><?php if($p['status_pedido']==='Pendente'): ?><form method="post" class="inline-form"><?= csrf() ?><input type="hidden" name="id_pedido" value="<?= (int)$p['id_pedido'] ?>"><label class="sr-only" for="purchase-<?= (int)$p['id_pedido'] ?>">Status da compra <?= (int)$p['id_pedido'] ?></label><select name="status" id="purchase-<?= (int)$p['id_pedido'] ?>"><option value="Comprado">Comprado e recebido</option><option>Não comprado</option></select><button class="button small">Confirmar</button></form><?php else: ?><span class="muted">Finalizada</span><?php endif ?></td></tr><?php endforeach; if(!$purchases): ?><tr><td colspan="6" class="empty">Nenhum pedido de compra registrado.</td></tr><?php endif ?></tbody></table></div></section>
